This would be similar to ```torch.cat``` or ```numpy.concatenate```.

Here is the code. Would anyone find this useful as a PR? I would.

```
template <int axis, typename M1, typename M2>
struct cat_op 
{    
    const M1& m1;
    const M2& m2;
    
    static_assert(axis == 0 or axis == 1, "bad axis value");
    static_assert(axis == 0 ? M1::NC == M2::NC or M1::NC == 0 or M2::NC == 0 : M1::NR == M2::NR or M1::NR == 0 or M2::NR == 0, "bad dims");
    static const long cost = M1::cost + M2::cost;
    static const long NR   = M1::NR == 0 or M2::NR == 0 ? 0 : (axis == 0 ? M1::NR + M2::NR : M1::NR);
    static const long NC   = M1::NC == 0 or M2::NC == 0 ? 0 : (axis == 0 ? M1::NC : M1::NC + M2::NC);
    typedef typename M1::type             type;
    typedef typename M1::mem_manager_type mem_manager_type;
    typedef typename M1::layout_type      layout_type;
    typedef typename M1::const_ret_type   const_ret_type;
    
    
    cat_op( const M1& m1_, const M2& m2_) : m1(m1_), m2(m2_) 
    {
        DLIB_ASSERT(axis == 0 ? m1_.nc() == m2_.nc() : m1_.nr() == m2_.nr(), "bad dims");
    }
    const_ret_type apply (long r, long c) const 
    {
        if (axis == 0) //either compiler will optimise this or branch prediction will
        {
            return r < m1.nr() ? m1(r,c) : m2(r-m1.nr(),c); //i reckon branch prediction will optimise this, unless you're doing random access.
        }
        else
        {
            return c < m1.nc() ? m1(r,c) : m2(r,c-m1.nc()); //i reckon branch prediction will optimise this, unless you're doing random access.
        }
    }
    long nr () const { return axis == 0 ? m1.nr() + m2.nr() : m1.nr();}
    long nc () const { return axis == 0 ? m1.nc() : m1.nc() + m2.nc(); }
    template <typename U> bool aliases               ( const dlib::matrix_exp<U>& item) const { return m1.aliases(item) || m2.aliases(item); }
    template <typename U> bool destructively_aliases ( const dlib::matrix_exp<U>& item) const { return m1.aliases(item) || m2.aliases(item); }
}; 

template <int axis, typename M1, typename M2>
const dlib::matrix_op<cat_op<axis,M1,M2> > cat (
    const dlib::matrix_exp<M1>& m1,
    const dlib::matrix_exp<M2>& m2
)
{
    typedef cat_op<axis,M1,M2> op;
    return dlib::matrix_op<op>(op(m1.ref(),m2.ref()));
}

void test_cat()
{
    dlib::matrix<int> a = dlib::ones_matrix<int>(3,2);
    dlib::matrix<int> b = dlib::ones_matrix<int>(4,2) * 2;
    dlib::matrix<int> c = cat<0>(a,b);
    
    cout << a << endl;
    cout << b << endl;
    cout << c << endl;
}
```

